624					t.Fatalf("stdout = %q, want completely empty on failure", res.stdout)
625				}
626				var fail struct {
627					Code   string `json:"code"`
628					Reason string `json:"reason"`
629				}
630				decodeOneJSON(t, res.stderr, "stderr", &fail)
631				if fail.Code != "invalid_request" {
632					t.Fatalf("code = %q, want invalid_request", fail.Code)
633				}
634				for _, want := range tc.want {
635					if !strings.Contains(fail.Reason, want) {
636						t.Errorf("reason = %q, want substring %q", fail.Reason, want)
637					}
638				}
639				for _, bad := range tc.forbidden {
640					if strings.Contains(fail.Reason, bad) {
641						t.Errorf("reason = %q must not contain %q", fail.Reason, bad)
642					}
643				}
644			})
645		}
