647		// A bad config is reported before the request is even examined, so a
648		// broken config paired with a broken request still yields invalid_config.
649		badConfig := `{"routes":[{"id":"x","methods":"GET","pathPrefix":"/a","upstream":"http://h"}]}`
650		res := runResolveCLI(t, badConfig, `{not json`)
651		if res.exitCode == 0 || len(res.stdout) != 0 {
652			t.Fatalf("got exit %d stdout %q, want non-zero exit and empty stdout", res.exitCode, res.stdout)
653		}
654		var fail struct {
655			Code string `json:"code"`
656		}
657		decodeOneJSON(t, res.stderr, "stderr", &fail)
658		if fail.Code != "invalid_config" {
659			t.Fatalf("code = %q, want invalid_config to take priority", fail.Code)
660		}
