1437		// Config validation still precedes request parsing: a bad config paired
1438		// with a newline target yields invalid_config, and stdout stays empty.
1439		badConfig := `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"ftp://h"}]}`
1440		res := runResolveCLI(t, badConfig, `{"method":"GET","target":"/a\n"}`)
1441		if res.exitCode == 0 || len(res.stdout) != 0 {
1442			t.Fatalf("got exit %d stdout %q, want non-zero exit and empty stdout", res.exitCode, res.stdout)
1443		}
1444		var fail struct {
1445			Code string `json:"code"`
1446		}
1447		decodeOneJSON(t, res.stderr, "stderr", &fail)
1448		if fail.Code != "invalid_config" {
1449			t.Fatalf("code = %q, want invalid_config to take priority", fail.Code)
1450		}
1451	}
1452	
1453	func TestResolveCLIRouteConflict(t *testing.T) {
1454		// alpha and zeta both concretely accept GET at the same /api prefix
1455		// with no longer prefix to win; the same-prefix wildcard route must not
1456		// appear among the final candidates.
