1458		  "routes": [
1459		    {"id": "zeta",  "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://z.internal/v1"},
1460		    {"id": "alpha", "methods": ["GET"], "pathPrefix": "/api", "upstream": "http://a.internal/v1"},
1461		    {"id": "wild",  "methods": ["*"],   "pathPrefix": "/api", "upstream": "http://w.internal/v1"}
1462		  ]
1463		}`
1464		res := runResolveCLI(t, config, cliSuccessRequest)
1465	
